    private Tab current(){return tabs.get(active);}
    private void addTab(){if(tabs.size()>=12){toast("Лимит альфа-версии: 12 вкладок");return;}Tab t=new Tab();t.web=new WebView(this);configure(t);tabs.add(t);active=tabs.size()-1;showTab();}
    private void closeTab(int index){Tab t=tabs.remove(index);if(shownTab==t)shownTab=null;if(t.web.getParent() instanceof android.view.ViewGroup)((android.view.ViewGroup)t.web.getParent()).removeView(t.web);t.web.stopLoading();t.web.destroy();if(tabs.isEmpty()){active=0;addTab();return;}if(index<active)active--;else if(active>=tabs.size())active=tabs.size()-1;showTab();}
    private void refreshTabs(){if(tabCount!=null){tabCount.setText(String.valueOf(tabs.size()));tabCount.setCompoundDrawablePadding(dp(5));tabCount.setCompoundDrawables(icon("▣",CYAN,20),null,null,null);}tabsBar.removeAllViews();for(int i=0;i<tabs.size();i++){final int n=i;Tab t=tabs.get(i);LinearLayout chip=row();chip.setBackground(shape(i==active?0xff30304f:PANEL,12,i==active?PURPLE:0));TextView title=label(t.home?"Новая вкладка":t.title,13,TEXT);title.setSingleLine(true);title.setEllipsize(android.text.TextUtils.TruncateAt.END);title.setMaxWidth(dp(130));title.setPadding(dp(10),dp(9),dp(8),dp(9));title.setOnClickListener(v->{active=n;showTab();});if(t.favicon!=null&&!t.home){ImageView fav=new ImageView(this);fav.setImageBitmap(t.favicon);add(chip,fav,18,18);}else {ImageView fav=new ImageView(this);fav.setImageDrawable(icon(t.home?"⚡":"◎",CYAN,18));add(chip,fav,18,18);}chip.addView(title);TextView x=button("×","Закрыть вкладку",()->closeTab(n));chip.addView(x,new LinearLayout.LayoutParams(dp(44),dp(44)));add(tabsBar,chip,-2,44);}add(tabsBar,button("+","Новая вкладка",()->addTab()),44,44);}
    private void showTab(){dismissPanel();captureShown();body.removeAllViews();Tab t=current();shownTab=t;if(t.home){address.setText("");body.addView(home(),new FrameLayout.LayoutParams(-1,-1));}else{if(t.web.getParent() instanceof android.view.ViewGroup)((android.view.ViewGroup)t.web.getParent()).removeView(t.web);body.addView(t.web,new FrameLayout.LayoutParams(-1,-1));address.setText(t.web.getUrl());}updateProgress(t);refreshTabs();address.clearFocus();}
    private void updateProgress(Tab t){if(!tabs.isEmpty()&&t==current()){progress.setProgress(t.progress);progress.setVisibility(!t.home&&t.progress>0&&t.progress<100?View.VISIBLE:View.INVISIBLE);}}
