    private void themes(){LinearLayout c=panel("Внешний вид","Фирменные варианты оформления",false);for(String theme:new String[]{"Космос","AMOLED","Графит"})item(c,"✧",theme,theme.equals("Космос")?"Планета и неоновые линии":theme.equals("AMOLED")?"Чёрный фон стартовой страницы":"Спокойный тёмный фон",appearance.equals(theme)?"●":"○",()->{appearance=theme;prefs.edit().putString("appearance",theme).apply();root.setBackgroundColor(themeBg());showTab();});}
    private void requestDownload(String url,String ua,String disposition,String mime){if(Router.parse(url).kind!=Router.Kind.WEB){toast("Адрес загрузки не поддерживается");return;}String guessed=URLUtil.guessFileName(url,disposition,mime);String name=guessed.replaceAll("[/\\\\\\p{Cntrl}]","_");if(name.length()>120)name=name.substring(0,120);final String safeName=name.isEmpty()?"download":name;LinearLayout c=panel("Загрузка","Сохранение файла",true);item(c,"↓",safeName,"HTTP(S) • системный менеджер загрузок","›",()->{try{DownloadManager.Request request=new DownloadManager.Request(Uri.parse(url));request.setTitle(safeName);request.setNotificationVisibility(DownloadManager.Request.VISIBILITY_VISIBLE_NOTIFY_COMPLETED);if(mime!=null)request.setMimeType(mime);if(ua!=null)request.addRequestHeader("User-Agent",ua);String cookie=CookieManager.getInstance().getCookie(url);if(cookie!=null&&url.startsWith("https://"))request.addRequestHeader("Cookie",cookie);String target=System.currentTimeMillis()+"-"+safeName;if(Build.VERSION.SDK_INT>=29)request.setDestinationInExternalPublicDir(Environment.DIRECTORY_DOWNLOADS,target);else request.setDestinationInExternalFilesDir(this,Environment.DIRECTORY_DOWNLOADS,target);long id=((DownloadManager)getSystemService(DOWNLOAD_SERVICE)).enqueue(request);remember(downloads,"downloads",id+"|"+safeName,100);downloadPanel();}catch(Exception e){notice("Ошибка загрузки",String.valueOf(e.getMessage()));}});item(c,"×","Отмена","","",()->dismissPanel());}
    private void downloadPanel(){LinearLayout c=panel("Загрузки","Файлы и состояние загрузок",false);DownloadManager dm=(DownloadManager)getSystemService(DOWNLOAD_SERVICE);item(c,"↻","Обновить список","","›",()->downloadPanel());if(downloads.isEmpty())section(c,"ПОКА НЕТ ЗАГРУЗОК");for(String entry:new ArrayList<>(downloads)){int split=entry.indexOf('|');if(split<1)continue;try{long id=Long.parseLong(entry.substring(0,split));String name=entry.substring(split+1),state="Недоступно";int status=-1;try(android.database.Cursor cur=dm.query(new DownloadManager.Query().setFilterById(id))){if(cur!=null&&cur.moveToFirst()){status=cur.getInt(cur.getColumnIndexOrThrow(DownloadManager.COLUMN_STATUS));long done=cur.getLong(cur.getColumnIndexOrThrow(DownloadManager.COLUMN_BYTES_DOWNLOADED_SO_FAR));long total=cur.getLong(cur.getColumnIndexOrThrow(DownloadManager.COLUMN_TOTAL_SIZE_BYTES));state=status==DownloadManager.STATUS_SUCCESSFUL?"Готово":status==DownloadManager.STATUS_FAILED?"Ошибка":total>0?(done*100/total)+"%":"В очереди / загружается";}}final int st=status;item(c,"↓",name,state,"›",()->{if(st==DownloadManager.STATUS_SUCCESSFUL){try{Uri u=dm.getUriForDownloadedFile(id);if(u==null)throw new IllegalStateException();Intent in=new Intent(Intent.ACTION_VIEW).setDataAndType(u,dm.getMimeTypeForDownloadedFile(id)).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(in);}catch(Exception e){toast("Открой файл через системные загрузки");}}else notice("Загрузка","Нажми «Обновить список» для проверки статуса.");});}catch(Exception ignored){}}item(c,"↗","Системные загрузки","","›",()->{try{startActivity(new Intent(DownloadManager.ACTION_VIEW_DOWNLOADS));}catch(Exception e){toast("Открой приложение Файлы");}});}


    private android.graphics.drawable.Drawable icon(String key,int color,int size){BoltIcon d=new BoltIcon(key,color);d.setBounds(0,0,dp(size),dp(size));return d;}
    private GradientDrawable glass(int radius,int stroke){GradientDrawable d=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{0xff242a49,0xff171d34,0xff10162b});d.setCornerRadius(dp(radius));if(stroke!=0)d.setStroke(dp(1),stroke);return d;}
    private android.graphics.drawable.Drawable glassRipple(int radius,int stroke){return new android.graphics.drawable.RippleDrawable(android.content.res.ColorStateList.valueOf(0x447f8cff),glass(radius,stroke),null);}
    private void captureShown(){Tab t=shownTab;if(t==null||!tabs.contains(t)||body==null||body.getChildCount()==0||body.getChildAt(0)!=t.web)return;WebView w=t.web;int width=w.getWidth(),height=w.getHeight();if(width<2||height<2)return;try{float scale=Math.min(1f,360f/Math.max(width,height));android.graphics.Bitmap b=android.graphics.Bitmap.createBitmap(Math.max(1,Math.round(width*scale)),Math.max(1,Math.round(height*scale)),android.graphics.Bitmap.Config.RGB_565);android.graphics.Canvas c=new android.graphics.Canvas(b);c.scale(scale,scale);c.translate(-w.getScrollX(),-w.getScrollY());w.draw(c);t.preview=b;}catch(RuntimeException ignored){}}
    private View previewFor(Tab t){FrameLayout frame=new FrameLayout(this);frame.setBackground(glass(13,0xff3d4772));frame.setClipToOutline(true);if(!t.home&&t.preview!=null){ImageView image=new ImageView(this);image.setImageBitmap(t.preview);image.setScaleType(ImageView.ScaleType.CENTER_CROP);frame.addView(image,new FrameLayout.LayoutParams(-1,-1));}else{if(t.home)frame.setBackground(new SpaceArt());LinearLayout center=column();center.setGravity(Gravity.CENTER);ImageView img=new ImageView(this);if(t.home)img.setImageResource(R.drawable.bolt);else if(t.favicon!=null)img.setImageBitmap(t.favicon);else img.setImageDrawable(icon("◎",CYAN,38));add(center,img,46,46);TextView name=label(t.home?"AetherBolt":t.title,12,TEXT);name.setGravity(Gravity.CENTER);name.setMaxLines(2);center.addView(name);frame.addView(center,new FrameLayout.LayoutParams(-1,-1));}return frame;}

    private void configure(Tab t){WebView w=t.web;WebSettings s=w.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(false);s.setAllowContentAccess(false);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);s.setSupportMultipleWindows(false);s.setJavaScriptCanOpenWindowsAutomatically(false);s.setMediaPlaybackRequiresUserGesture(true);s.setSafeBrowsingEnabled(true);s.setBuiltInZoomControls(true);s.setDisplayZoomControls(false);CookieManager.getInstance().setAcceptThirdPartyCookies(w,false); applyOptions(t);
        w.setWebChromeClient(new WebChromeClient(){@Override public void onProgressChanged(WebView v,int p){t.progress=p;updateProgress(t);}@Override public void onReceivedIcon(WebView v,android.graphics.Bitmap b){if(tabs.contains(t)){t.favicon=b;refreshTabs();}}@Override public void onReceivedTitle(WebView v,String title){if(tabs.contains(t)&&title!=null&&!title.trim().isEmpty()){t.title=title;refreshTabs();}}});
        w.setWebViewClient(new WebViewClient(){
            @Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest req){Router.Target target=Router.parse(req.getUrl().toString());if(target.kind!=Router.Kind.WEB){if(req.isForMainFrame())toast(target.kind==Router.Kind.ONION?"Tor пока не встроен; адрес заблокирован":"Неподдерживаемый адрес");return true;}return false;}
            @Override public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest req){String host=req.getUrl().getHost();if(Router.onionHost(host)||(!req.isForMainFrame()&&((filter&&isAdHost(host))||(tracker&&isTrackerHost(host)))))return new WebResourceResponse("text/plain","UTF-8",new ByteArrayInputStream(new byte[0]));return null;}
            @Override public void onPageStarted(WebView v,String url,android.graphics.Bitmap favicon){if(Router.onionHost(Uri.parse(url).getHost())){v.stopLoading();toast("Tor не подключён");return;}if(!tabs.isEmpty()&&t==current()&&!t.home&&!address.hasFocus())address.setText(url);}
            @Override public void onPageFinished(WebView v,String url){if(Router.parse(url).kind==Router.Kind.WEB){if(historyEnabled)remember(history,"history",url,200); if(darkPages&&js)applyDark(v);if(!tabs.isEmpty()&&t==current()&&!t.home&&!address.hasFocus())address.setText(url);}}
        });
        w.setDownloadListener((url,agent,disposition,mime,length)->requestDownload(url,agent,disposition,mime));
    }
    private boolean isAdHost(String h){if(h==null)return false;h=h.toLowerCase(Locale.ROOT);for(String domain:new String[]{"doubleclick.net","googlesyndication.com","googleadservices.com","adnxs.com","adsrvr.org"})if(h.equals(domain)||h.endsWith("."+domain))return true;return false;}
    private void navigate(String raw){Router.Target target=Router.resolve(raw,engineTemplate);if(target.kind==Router.Kind.ONION){notice("Сеть Tor","Распознан .onion-адрес. Tor пока не реализован, поэтому адрес не загружен.");return;}if(target.kind==Router.Kind.INVALID){toast("Введите корректный HTTP(S)-адрес или запрос");return;}((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(address.getWindowToken(),0);Tab t=current();t.home=false;showTab();address.setText(target.url);t.web.loadUrl(target.url);}
    private void back(){if(overlay!=null){dismissPanel();return;}Tab t=current();if(!t.home&&t.web.canGoBack()){t.web.goBack();}else if(!t.home){t.home=true;showTab();}else if(tabs.size()>1){closeTab(active);}else{super.onBackPressed();}}
    @Override public void onBackPressed(){back();}
    private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_SHORT).show();}
