    private void customEngine(){LinearLayout c=panel("Свой поисковик","Укажи название и адрес поиска",false);EditText name=field("Название"),url=field("https://example.org/search?q={query}");add(c,name,-1,54);add(c,url,-1,54);TextView hint=label("Используй {query} вместо поискового запроса.",13,MUTED);add(c,hint,-1,-2);item(c,"✓","Сохранить","","›",()->{String n=name.getText().toString().trim(),u=url.getText().toString().trim();if(n.isEmpty()||!Router.validTemplate(u)){url.setError("Нужен HTTP(S)-шаблон с {query}");return;}dismissPanel();setEngine(n,u);});}
    private void tabDialog(){captureShown();LinearLayout c=panel("Вкладки ("+tabs.size()+")","Открытые страницы",false);int cols=getResources().getConfiguration().screenWidthDp>=720?3:2;for(int i=0;i<tabs.size()+1;i+=cols){LinearLayout r=row();r.setGravity(Gravity.TOP);for(int j=i;j<Math.min(i+cols,tabs.size()+1);j++){final int n=j;LinearLayout card=column();card.setPadding(dp(8),dp(8),dp(8),dp(8));card.setBackground(glassRipple(19,j==active?PURPLE:0xff34405c));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(205),1);p.setMargins(dp(5),dp(5),dp(5),dp(5));r.addView(card,p);if(j==tabs.size()){LinearLayout center=column();center.setGravity(Gravity.CENTER);ImageView plus=new ImageView(this);plus.setImageDrawable(icon("+",PURPLE,34));add(center,plus,48,48);TextView t=label("Новая вкладка",13,TEXT);t.setGravity(Gravity.CENTER);center.addView(t);card.addView(center,new LinearLayout.LayoutParams(-1,0,1));card.setOnClickListener(v->addTab());continue;}Tab t=tabs.get(j);LinearLayout h=row();ImageView fav=new ImageView(this);if(t.favicon!=null&&!t.home)fav.setImageBitmap(t.favicon);else fav.setImageDrawable(icon(t.home?"⚡":"◎",CYAN,20));add(h,fav,20,20);TextView title=label(t.home?"Новая вкладка":t.title,12,TEXT);title.setMaxLines(1);title.setEllipsize(android.text.TextUtils.TruncateAt.END);h.addView(title,new LinearLayout.LayoutParams(0,-2,1));add(h,button("×","Закрыть",()->{closeTab(n);tabDialog();}),44,44);card.addView(h);View preview=previewFor(t);card.addView(preview,new LinearLayout.LayoutParams(-1,0,1));preview.setOnClickListener(v->{active=n;showTab();});card.setOnClickListener(v->{active=n;showTab();});}for(int j=Math.min(i+cols,tabs.size()+1);j<i+cols;j++){View filler=new View(this);r.addView(filler,new LinearLayout.LayoutParams(0,dp(205),1));}c.addView(r);}item(c,"+","Открыть новую вкладку","","›",()->addTab());}
    private void menu(){LinearLayout c=panel("AetherBolt ⚡","Быстрый доступ",true);grid(c,new String[]{"Новая вкладка","Вкладки","Закладки","История","Поисковики","Настройки","Дополнения","Загрузки","Версия для ПК"},new String[]{"+","▣","☆","◷","⌕","⚙","✧","↓","▣"},new int[]{CYAN,PURPLE},new Runnable[]{()->addTab(),()->tabDialog(),()->listDialog("Закладки",bookmarks,"bookmarks"),()->listDialog("История",history,"history"),()->engineDialog(),()->settings(),()->plugins(),()->downloadPanel(),()->toggle("desktop",!desktop,()->{dismissPanel();if(!current().home)current().web.reload();})},3);}
